279	    @Test void associationReflectsPostParseChanges() {
280	        String html = "<form id='a'><input id='i' name='n' value='1'></form><form id='b'></form>";
281	        Document doc = Jsoup.parse(html);
282	        FormElement a = doc.expectForm("#a");
283	        FormElement b = doc.expectForm("#b");
284	        Element input = doc.getElementById("i");
285	
286	        // add a form attribute: re-home from ancestor form a to form b
287	        input.attr("form", "b");
288	        assertEquals(0, a.formData().size());
289	        assertEquals("n=1", b.formData().get(0).toString());
290	
291	        // remove it: back to the nearest ancestor (it is still inside form a's subtree)
292	        input.removeAttr("form");
293	        assertEquals("n=1", a.formData().get(0).toString());
294	        assertEquals(0, b.formData().size());
295	
296	        // physically move the control outside both forms; explicit attr still resolves to form b
297	        doc.body().appendChild(input);
298	        assertEquals(0, a.formData().size()); // no longer a descendant, no parser-style retention here
299	        input.attr("form", "b");
300	        assertEquals("n=1", b.formData().get(0).toString());
301	
302	        // the referenced form changes its id: the dangling reference resolves nowhere, no ancestor fallback
303	        b.attr("id", "c");
304	        assertEquals(0, a.formData().size());
305	        assertEquals(0, b.formData().size());
306	    }
